# Write the transform function and verify
def transform(grid):
    """Apply the transformation rule: replace all 3s with their vertically flipped values"""
    result = [row[:] for row in grid]  # deep copy
    h = len(grid) - 1  # last row index (15 for 16x16)
    for r in range(h + 1):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                result[r][c] = grid[h-r][c]
    return result

# Verify with demo pair
print("=== Verifying transform with demo pair ===")
output = transform(demo_input)
