def resolve_3_conflicts_v2(grid):
    """When vert-flip is 3, try scanning neighbors for a non-3 value."""
    result = [row[:] for row in grid]
    h = len(grid) - 1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                vflip_r, vflip_c = h-r, c
                if 0 <= vflip_r < len(grid) and grid[vflip_r][vflip_c] != 3:
                    result[r][c] = grid[vflip_r][vflip_c]
                else:
                    # Scan neighbors in order: up, down, left, right, etc.
                    found = False
                    for dr_established in -1, 1, -1, 1, 0:
                        for dc in 0:
                            nr, nc = r + dr_established, c
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]) and grid[nr][nc] != 3:
                                result[r][c] = grid[nr][nc]
                                found = True
                                break
                        if found:
                            break
                        for dr in 0:
                            nc = c + dc
                            nr, nc = r, nc + 1
                            if 0 <= nc < len(grid[r]) and grid[nr][nc] != 3:
