# Try using BOTTOM edge instead of top edge for conflicts

def resolve_3_bottom_edge(grid):
    result = [row[:] for row in grid]
    h = len(grid) - 1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                vflip_r, vflip_c = h-r, c
                if grid[vflip_r][vflip_c] != 3:
                    result[r][c] = grid[vflip_r][vflip_c]
                else:
                    # Use bottom edge
                    result[r][c] = grid[-1][c]  # Last row
    return result

output_bottom = resolve_3_bottom_edge(test_input)

# Check remaining 3s
remaining = 0
for r in range(len(output_bottom)):
    for c in range(len(output_bottom[r])):
        if output_bottom[r][c] == 3:
            remaining += 1

print(f"Remaining 3s with bottom-edge fallback: {remaining}")

print("\n=== Output with bottom-edge fallback ===")
for row in output_bottom:
    print(row)

# Let me check: what if 3s are replaced by their vertical flip, but when flip is 3,
# we use a different strategy - maybe fill with the LEFT neighbor?

def resolve_3_left_neighbor(grid):
    result = [row[:] for row in grid]
    h = len(grid) - 1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                vflip_r, vflip_c = h-r, c
                if grid[vflip_r][vflip_c] != 3:
                    result[r][c] = grid[vflip_r][vflip_c]
                else:
                    # Use left neighbor
                    if c > 0:
                        result[r][c] = grid[r][c-1]
                    else:
                        # No left neighbor, use top edge
                        result[r][c] = grid[0][c]
    return result

