# Try: vertical flip, and when vert-flip is 3, use 180° rotation value

def resolve_3_hybrid(grid):
    result = [row[:] for row in grid]
    h = len(grid) - 1

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                vflip_r, vflip_c = h-r, c
